const manifestPromise = game.manifest
  ? fetch(game.manifest, { cache: 'no-store' }).then((response) => {
      if (!response.ok) throw new Error(`โหลด manifest ไม่สำเร็จ (${response.status})`);
      return response.json();
    })
  : Promise.resolve(null);

if (game.manifest) {
  workspaceStatus.textContent = 'XDELTA3 READY';
  workspaceNote.innerHTML = '<span>แพตช์จริง</span> ระบบจะตรวจขนาดและ SHA-256 ของ ROM ต้นฉบับ จากนั้นรัน xdelta3 ภายในเบราว์เซอร์ ไฟล์ ROM จะไม่ถูกอัปโหลดออกจากเครื่อง แนะนำให้ทดสอบบนคอมพิวเตอร์ก่อน';
  void manifestPromise.then((manifest) => {
    const verification = manifest.verification;
    const roundtripVerified = Boolean(
      verification?.source_sha256_verified &&
      verification?.patch_sha256_verified &&
      verification?.output_sha256_verified &&
      verification?.output_matches_release_target
    );
    const patcherTestPassed = verification?.patcher_test_passed === true;
    document.querySelector('#detail-status').textContent = roundtripVerified
      ? 'ผ่านการทดสอบบนเว็บ'
      : patcherTestPassed
        ? 'ผ่านการทดสอบ xdelta'
        : 'พร้อมทดลอง · รอยืนยันรอบจริง';
    workspaceStatus.textContent = roundtripVerified || patcherTestPassed
      ? 'XDELTA3 VERIFIED'
      : 'XDELTA3 READY · VERIFYING';

    if (manifest.output.size >= 512 * 1024 * 1024) {
      workspaceNote.insertAdjacentHTML(
        'beforeend',
        '<br /><span>ไฟล์ขนาดใหญ่</span> รุ่นนี้อาจต้องใช้หน่วยความจำมากในขั้นสร้างไฟล์ผลลัพธ์ ควรใช้ Chrome/Edge บนคอมพิวเตอร์และปิดโปรแกรมที่ไม่จำเป็น',
      );
    }
  }).catch(() => {
    document.querySelector('#detail-status').textContent = 'โหลดข้อมูลแพตช์ไม่สำเร็จ';
    workspaceStatus.textContent = 'MANIFEST ERROR';
  });
}

const formatBytes = (bytes) => {
  if (!bytes) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  return `${(bytes / (1024 ** index)).toFixed(index > 1 ? 2 : 0)} ${units[index]}`;
};

const showToast = (message) => {
  toast.textContent = message;
  toast.classList.add('show');
  window.setTimeout(() => toast.classList.remove('show'), 3200);
};

const setProgress = (label, percent) => {
  const safePercent = Math.max(0, Math.min(100, Math.round(percent)));
  patchProgress.hidden = false;
  patchProgressLabel.textContent = label;
  patchProgressPercent.textContent = `${safePercent}%`;
  patchProgressBar.style.width = `${safePercent}%`;
};

const sha256Blob = async (blob, onProgress = () => {}) => {
  const hasher = new IncrementalSHA256();
  const reader = blob.stream().getReader();
  let processed = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    hasher.update(value);
    processed += value.byteLength;
    onProgress(processed, blob.size);
    await new Promise((resolve) => window.setTimeout(resolve, 0));
  }

  return hasher.digestHex();
};

const resetOutput = () => {
  if (outputUrl) URL.revokeObjectURL(outputUrl);
  outputUrl = null;
  downloadButton.hidden = true;
  downloadButton.removeAttribute('href');
};

const handleFile = async (file) => {
  if (!file) return;
  resetOutput();
  selectedSourceFile = null;
  patchButton.disabled = true;
  dropZone.classList.remove('is-valid', 'is-invalid');
  fileName.textContent = file.name;
  fileSize.textContent = formatBytes(file.size);
  dropZone.querySelector('h3').textContent = 'เลือกไฟล์ของเกมนี้แล้ว';
  dropZone.querySelector('p').innerHTML = 'ไฟล์ยังอยู่ในอุปกรณ์ของคุณ<br />ไม่มีการอัปโหลดเกิดขึ้น';

  if (!game.manifest) {
    fileHash.textContent = 'พร้อมตรวจเมื่อเชื่อมรายการ source hash';
    patchButton.disabled = false;
    patchButton.querySelector('span').textContent = 'ตรวจไฟล์และเริ่มแพตช์';
    return;
  }

  try {
    const manifest = await manifestPromise;
    const sizeCandidates = manifest.accepted_sources.filter((source) => file.size === source.size);
    if (sizeCandidates.length === 0) {
      const supportedSizes = [...new Set(manifest.accepted_sources.map((source) => formatBytes(source.size)))].join(' / ');
      fileHash.textContent = `ขนาดไม่ตรง — รองรับ ${supportedSizes}`;
      dropZone.classList.add('is-invalid');
      patchButton.querySelector('span').textContent = 'ROM ไม่ตรงรุ่น';
      showToast(`ROM มีขนาดไม่ตรงกับ ${manifest.region || 'รุ่น'} ที่รองรับ`);
      return;
    }

    setProgress('กำลังตรวจ SHA-256 ของ ROM ต้นฉบับ', 2);
    fileHash.textContent = 'กำลังคำนวณ SHA-256…';
    const sourceHash = await sha256Blob(file, (processed, total) => {
      setProgress('กำลังตรวจ SHA-256 ของ ROM ต้นฉบับ', 2 + (processed / total) * 3);
    });
    const matchedSource = sizeCandidates.find((source) => source.sha256 === sourceHash);
    if (!matchedSource) {
      fileHash.textContent = `${sourceHash.slice(0, 16)}… — ไม่ตรงรุ่น`;
      dropZone.classList.add('is-invalid');
      patchButton.querySelector('span').textContent = 'SHA-256 ไม่ตรง';
      setProgress('ROM ต้นฉบับไม่ตรงกับรุ่นที่รองรับ', 0);
      showToast('SHA-256 ไม่ตรง — ระบบจะไม่แพตช์ไฟล์นี้');
      return;
    }

    selectedSourceFile = file;
    fileHash.textContent = `${sourceHash.slice(0, 16)}… — ถูกต้อง`;
    dropZone.classList.add('is-valid');
    patchButton.disabled = false;
    patchButton.querySelector('span').textContent = `เริ่มแพตช์ ${manifest.patch_version}`;
    setProgress('ROM ต้นฉบับผ่านการตรวจสอบ', 5);
  } catch (error) {
    fileHash.textContent = 'ตรวจไฟล์ไม่สำเร็จ';
    dropZone.classList.add('is-invalid');
    showToast(error.message || 'เกิดข้อผิดพลาดขณะตรวจ ROM');
  }
};

dropZone.addEventListener('click', () => romInput.click());
dropZone.addEventListener('keydown', (event) => {
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    romInput.click();
  }
});
romInput.addEventListener('change', () => void handleFile(romInput.files[0]));

['dragenter', 'dragover'].forEach((type) => {
  dropZone.addEventListener(type, (event) => {
    event.preventDefault();
    dropZone.classList.add('is-dragging');
  });
});
['dragleave', 'drop'].forEach((type) => {
  dropZone.addEventListener(type, (event) => {
    event.preventDefault();
    dropZone.classList.remove('is-dragging');
  });
});
dropZone.addEventListener('drop', (event) => void handleFile(event.dataTransfer.files[0]));

const applyVerifiedPatch = async () => {
  if (!selectedSourceFile) return;
  const manifest = await manifestPromise;
  patchButton.disabled = true;
  resetOutput();

  try {
    setProgress('กำลังดาวน์โหลดและตรวจไฟล์ patch', 7);
    const manifestBase = new URL(game.manifest, window.location.href);
    const fetchFirstOk = async (urls) => {
      let lastError = 'Network error';
      for (const url of urls.filter((u, i, all) => u && all.indexOf(u) === i)) {
        try {
          const res = await fetch(url, { cache: 'no-store' });
          if (res.ok) return res;
          lastError = `HTTP ${res.status}`;
        } catch (e) {
          lastError = 'Network error';
        }
      }
      throw new Error(`ดาวน์โหลด patch ไม่สำเร็จ (${lastError}) กรุณาลองใหม่หรือรีเฟรชหน้าเว็บ`);
    };

    let patchBlob;
    if (Array.isArray(manifest.patch.parts) && manifest.patch.parts.length) {
      // Patches over GitHub's 100 MB file limit are shipped as same-origin parts.
      const blobs = [];
      const parts = manifest.patch.parts;
      for (let i = 0; i < parts.length; i += 1) {
        setProgress(`กำลังดาวน์โหลด patch ส่วนที่ ${i + 1}/${parts.length}`, 2 + (i / parts.length) * 5);
        const res = await fetchFirstOk([new URL(parts[i].filename, manifestBase).href]);
        const blob = await res.blob();
        if (blob.size !== parts[i].size) throw new Error(`ขนาด patch ส่วนที่ ${i + 1} ไม่ตรงกับ manifest`);
        blobs.push(blob);
      }
      patchBlob = new Blob(blobs, { type: 'application/octet-stream' });
    } else {
      // Prefer the same-origin copy shipped with the site (GitHub Pages); the
      // external host is only a fallback because it may block cross-origin reads.
      const response = await fetchFirstOk([new URL(manifest.patch.filename, manifestBase).href, manifest.patch.url]);
      patchBlob = await response.blob();
    }
    if (patchBlob.size !== manifest.patch.size) throw new Error('ขนาดไฟล์ patch ไม่ตรงกับ manifest');
    const patchHash = await sha256Blob(patchBlob, (processed, total) => {
      setProgress('กำลังตรวจ SHA-256 ของไฟล์ patch', 7 + (processed / total) * 3);
    });
    if (patchHash !== manifest.patch.sha256) throw new Error('SHA-256 ของไฟล์ patch ไม่ถูกต้อง');

    setProgress('กำลังสร้าง ROM ภาษาไทยด้วย xdelta3', 10);
    const chunks = [];
    let outputSize = 0;
    const worker = new Worker('./assets/engine/xdelta/xdelta3.worker.js', { type: 'module' });

    await new Promise((resolve, reject) => {
      worker.onerror = (event) => reject(new Error(event.message || 'xdelta worker ทำงานไม่สำเร็จ'));
      worker.onmessage = (event) => {
        const message = event.data || {};
        if (!message.final && message.bytes) {
          const bytes = message.bytes instanceof Uint8Array ? message.bytes : new Uint8Array(message.bytes);
          chunks.push(bytes);
          outputSize += bytes.byteLength;
          const percent = 10 + (outputSize / manifest.output.size) * 78;
          setProgress('กำลังสร้าง ROM ภาษาไทยด้วย xdelta3', percent);
          return;
        }
        if (message.final && message.error) {
          reject(new Error(message.errorMessage || `xdelta error ${message.errorCode || ''}`));
          return;
        }
        if (message.final) resolve();
      };
      worker.postMessage({
        command: 'start',
        sourceFile: selectedSourceFile,
        patchFile: patchBlob,
        disableChecksum: false,
      });
    }).finally(() => worker.terminate());

    const outputBlob = new Blob(chunks, { type: 'application/octet-stream' });
    if (outputBlob.size !== manifest.output.size) throw new Error('ขนาด ROM ผลลัพธ์ไม่ตรงกับ manifest');

    setProgress('กำลังตรวจ SHA-256 ของ ROM ผลลัพธ์', 92);
    const outputHash = await sha256Blob(outputBlob, (processed, total) => {
      setProgress('กำลังตรวจ SHA-256 ของ ROM ผลลัพธ์', 92 + (processed / total) * 7);
    });
    if (outputHash !== manifest.output.sha256) throw new Error('SHA-256 ของ ROM ผลลัพธ์ไม่ถูกต้อง');

    outputUrl = URL.createObjectURL(outputBlob);
    downloadButton.href = outputUrl;
    downloadButton.download = manifest.output.filename;
    downloadButton.hidden = false;
    patchButton.querySelector('span').textContent = 'แพตช์สำเร็จ';
    fileHash.textContent = `${outputHash.slice(0, 16)}… — ผลลัพธ์ถูกต้อง`;
    setProgress('แพตช์และตรวจผลลัพธ์สำเร็จ', 100);
    showToast(`แพตช์สำเร็จและ SHA-256 ตรงกับ release ${manifest.patch_version}`);
    // Count only verified successes; a stats failure must never affect the patch result.
    if (window.PatchStats) window.PatchStats.hit(slug).then((value) => { if (value !== null) renderPatchCount(value); });
  } catch (error) {
    patchButton.disabled = false;
    patchButton.querySelector('span').textContent = 'ลองแพตช์อีกครั้ง';
    setProgress(error.message || 'แพตช์ไม่สำเร็จ', 0);
    showToast(error.message || 'เกิดข้อผิดพลาดขณะแพตช์');
  }
};

patchButton.addEventListener('click', () => {
  if (!game.manifest) {
    showToast(`ยังไม่พบ manifest สำหรับ ${game.title}`);
    return;
  }
  void applyVerifiedPatch();
});
